// Experimental benchmark only. Inputs are validated/generated by the harness.
// Eight i32 values per command: op, x, y, w, h, color, sx, sy.
// op 0 fills; op 1 copies from a 256-wide atlas. Fixed 256x192 contract.
#[no_mangle]
pub unsafe extern "C" fn compose(atlas: *const u8, commands: *const i32, count: usize, output: *mut u8, background: u8) {
    let pixels = std::slice::from_raw_parts_mut(output, 256 * 192);
    pixels.fill(background & 15);
    let atlas = std::slice::from_raw_parts(atlas, 256 * 128);
    let commands = std::slice::from_raw_parts(commands, count * 8);
    for c in commands.chunks_exact(8) {
        for y in 0..c[4] {
            let dy = c[2] + y;
            if dy < 0 || dy >= 192 { continue; }
            for x in 0..c[3] {
                let dx = c[1] + x;
                if dx < 0 || dx >= 256 { continue; }
                pixels[(dy * 256 + dx) as usize] = if c[0] == 0 { (c[5] & 15) as u8 }
                    else { atlas[((c[7] + y) * 256 + c[6] + x) as usize] };
            }
        }
    }
}

#[no_mangle]
pub extern "C" fn allocate(bytes: usize) -> *mut u8 {
    // One fixed allocation per benchmark instance, released with the instance.
    let mut data = vec![0u32; (bytes + 3) / 4].into_boxed_slice();
    let ptr = data.as_mut_ptr() as *mut u8;
    std::mem::forget(data);
    ptr
}
